import logging
from typing import Any

from mlflow.exceptions import MlflowException
from mlflow.protos.databricks_pb2 import INVALID_PARAMETER_VALUE

_logger = logging.getLogger(__name__)


class _DiffusersAdapterWrapper:
    """
    PyFunc wrapper for diffusion model adapters. The wrapper lazily loads the base
    ``DiffusionPipeline`` and applies the saved adapter weights, then generates images
    from text prompts.
    """

    def __init__(self, adapter_path: str, flavor_conf: dict, model_config: dict | None = None):
        self._adapter_path = adapter_path
        self._flavor_conf = flavor_conf
        self._model_config = model_config or {}
        self._pipeline = None

    def _base_model(self) -> str:
        # A ``base_model`` override supplied through ``model_config`` takes precedence over the
        # value stored in the flavor configuration.
        if "base_model" in self._model_config:
            return self._model_config["base_model"]
        return self._flavor_conf["base_model"]

    def _load_pipeline(self):
        import diffusers

        base_model = self._base_model()
        revision = self._flavor_conf.get("base_model_revision")
        from_pretrained_kwargs = {}
        if revision:
            from_pretrained_kwargs["revision"] = revision
        try:
            pipeline = diffusers.DiffusionPipeline.from_pretrained(
                base_model, **from_pretrained_kwargs
            )
        except OSError as e:
            raise MlflowException(
                f"Failed to load base model '{base_model}': {e}"
            ) from e

        self._apply_adapter(pipeline)
        return pipeline

    def _apply_adapter(self, pipeline):
        weight_name = self._flavor_conf.get("weight_name")
        load_kwargs = {}
        if weight_name:
            load_kwargs["weight_name"] = weight_name
        try:
            pipeline.load_lora_weights(self._adapter_path, **load_kwargs)
        except Exception as e:
            _logger.warning("Failed to load adapter weights from %s: %s", self._adapter_path, e)

    def _get_pipeline(self):
        if self._pipeline is None:
            self._pipeline = self._load_pipeline()
        return self._pipeline

    def get_raw_model(self):
        return self._get_pipeline()

    def _extract_prompts(self, data) -> list:
        import pandas as pd

        if isinstance(data, str):
            return [data]
        if isinstance(data, list):
            return list(data)
        if isinstance(data, dict):
            if "prompt" not in data:
                raise MlflowException(
                    "The input dictionary must contain a 'prompt' key.",
                    error_code=INVALID_PARAMETER_VALUE,
                )
            value = data["prompt"]
            if isinstance(value, str):
                return [value]
            if isinstance(value, list):
                return list(value)
            raise MlflowException(
                "The 'prompt' value must be a string or list of strings.",
                error_code=INVALID_PARAMETER_VALUE,
            )
        if isinstance(data, pd.DataFrame):
            if "prompt" in data.columns:
                return data["prompt"].tolist()
            if len(data.columns) == 1:
                return data[data.columns[0]].tolist()
            raise MlflowException(
                "The input DataFrame must contain a 'prompt' column.",
                error_code=INVALID_PARAMETER_VALUE,
            )
        raise MlflowException(
            f"Unsupported input type: {type(data)}. Expected a string, list of strings, "
            "dict with a 'prompt' key, or a pandas DataFrame.",
            error_code=INVALID_PARAMETER_VALUE,
        )

    def predict(self, data, params: dict[str, Any] | None = None) -> list[bytes]:
        prompts = self._extract_prompts(data)

        if len(prompts) == 0:
            raise MlflowException(
                "No prompts were provided for inference.",
                error_code=INVALID_PARAMETER_VALUE,
            )
        if any(prompt is None for prompt in prompts):
            raise MlflowException(
                "All prompt values must be strings, not None.",
                error_code=INVALID_PARAMETER_VALUE,
            )

        pipeline = self._get_pipeline()
        call_kwargs = dict(params) if params else {}
        output = pipeline(prompt=prompts, **call_kwargs)

        images = getattr(output, "images", None)
        if images is None or len(images) == 0:
            raise MlflowException(
                "Pipeline returned no images.",
                error_code=INVALID_PARAMETER_VALUE,
            )

        return [self._image_to_png_bytes(image) for image in images]

    @staticmethod
    def _image_to_png_bytes(image) -> bytes:
        buffer = io.BytesIO()
        image.save(buffer, format="PNG")
        return buffer.getvalue()
